-- Ajuste da tabela existente 'shops' para receber as novas colunas
ALTER TABLE shops 
ADD COLUMN IF NOT EXISTS state VARCHAR(2),
ADD COLUMN IF NOT EXISTS rating DECIMAL(2,1),
ADD COLUMN IF NOT EXISTS total_reviews INT,
ADD COLUMN IF NOT EXISTS lat DECIMAL(10,7),
ADD COLUMN IF NOT EXISTS lng DECIMAL(10,7),
ADD COLUMN IF NOT EXISTS place_id VARCHAR(100);

-- Inserindo os dados (id foi removido para permitir que o banco gere UUIDs automaticamente)
